-- Milestone 5: UTC daily retention, achievements, rotating demand, telemetry, and admin visibility.
alter table public.profiles add column app_role text not null default 'player' check(app_role in('player','admin'));
alter table public.player_season_progress add column longest_streak int not null default 0;
alter table public.player_season_progress add column last_active_quest_date date;
alter table public.player_season_progress add column weekly_cycle_claimed int not null default 0;
alter table public.economy_transactions add column economy_version int not null default 1;
alter table public.market_transactions add column economy_version int not null default 1;
alter table public.business_productions add column economy_version int not null default 1;

create table public.founder_point_history(id uuid primary key default gen_random_uuid(),player_id uuid not null references public.profiles(id) on delete cascade,amount int not null check(amount>0),reason text not null check(reason in('DAILY_QUEST','WEEKLY_STREAK','ACHIEVEMENT','OTHER')),reference_id uuid not null unique,created_at timestamptz not null default now());
create table public.achievement_claims(player_id uuid not null references public.profiles(id) on delete cascade,achievement_id text not null,claimed_at timestamptz not null default now(),reference_id uuid not null unique,primary key(player_id,achievement_id));
create table public.player_daily_orders(player_id uuid not null references public.profiles(id) on delete cascade,order_date date not null,order_id text not null references public.npc_orders(id),slot int not null check(slot between 1 and 3),created_at timestamptz not null default now(),primary key(player_id,order_date,slot),unique(player_id,order_date,order_id));
alter table public.player_orders add column order_date date not null default(current_date);
alter table public.player_orders drop constraint player_orders_pkey;
alter table public.player_orders add primary key(player_id,order_id,order_date);
insert into public.npc_orders(id,title) values('feed_workers','Feed the Workers'),('workshop_repairs','Workshop Repairs'),('road_reinforcement','Road Reinforcement'),('tool_delivery','Tool Delivery') on conflict do nothing;
create table public.action_telemetry(id bigserial primary key,player_id uuid references public.profiles(id) on delete cascade,event_type text not null,success boolean not null default true,occurred_at timestamptz not null default now(),metadata jsonb not null default '{}');
create index action_telemetry_player_time on public.action_telemetry(player_id,occurred_at desc);
create table public.abuse_signals(id bigserial primary key,player_id uuid references public.profiles(id) on delete cascade,signal text not null,score int not null default 1,details jsonb not null default '{}',created_at timestamptz not null default now(),reviewed_at timestamptz);
create trigger fp_history_immutable before update or delete on public.founder_point_history for each row execute procedure public.reject_ledger_mutation();
create trigger achievement_claims_immutable before update or delete on public.achievement_claims for each row execute procedure public.reject_ledger_mutation();

alter table public.founder_point_history enable row level security; alter table public.achievement_claims enable row level security; alter table public.player_daily_orders enable row level security; alter table public.action_telemetry enable row level security; alter table public.abuse_signals enable row level security;
create policy "read own fp history" on public.founder_point_history for select using(player_id=auth.uid()); create policy "read own achievements" on public.achievement_claims for select using(player_id=auth.uid()); create policy "read own daily orders" on public.player_daily_orders for select using(player_id=auth.uid());
revoke insert,update,delete on public.founder_point_history,public.achievement_claims,public.player_daily_orders,public.action_telemetry,public.abuse_signals from authenticated,anon;

create or replace function public.ensure_daily_state(pid uuid) returns void language plpgsql security definer set search_path='' as $$
declare quest text; order_ids text[]:=array['repair_old_bridge','feed_workers','workshop_repairs','road_reinforcement','tool_delivery']; picked text; slot_no int; seed bigint;
begin
 foreach quest in array array['daily-jobs-3','daily-order-1','daily-trades-2','daily-business-1'] loop insert into public.player_quests(player_id,quest_id,quest_date) values(pid,quest,current_date) on conflict do nothing; end loop;
 if not exists(select 1 from public.player_daily_orders where player_id=pid and order_date=current_date) then
  seed:=abs(hashtextextended(pid::text||current_date::text,0));
  for slot_no in 1..3 loop picked:=order_ids[1+((seed+slot_no*7919)%array_length(order_ids,1))::int]; while exists(select 1 from public.player_daily_orders where player_id=pid and order_date=current_date and order_id=picked) loop seed:=seed+1;picked:=order_ids[1+((seed+slot_no*7919)%array_length(order_ids,1))::int];end loop;insert into public.player_daily_orders values(pid,current_date,picked,slot_no,now());end loop;
 end if;
end $$;
create or replace function public.check_rate_limit(pid uuid,event_name text,max_actions int,window_seconds int) returns void language plpgsql security definer set search_path='' as $$
declare count_actions int;begin select count(*) into count_actions from public.action_telemetry where player_id=pid and event_type=event_name and occurred_at>clock_timestamp()-make_interval(secs=>window_seconds);if count_actions>=max_actions then insert into public.abuse_signals(player_id,signal,details) values(pid,'RATE_LIMIT',jsonb_build_object('event',event_name,'count',count_actions));raise exception 'RATE_LIMITED';end if;end $$;

alter function public.get_player_game_state(uuid) rename to get_player_game_state_milestone4;
create or replace function public.get_player_game_state(target_player uuid default auth.uid()) returns jsonb language plpgsql security definer set search_path='' as $$
declare base jsonb; fp int; current_rank text; next_rank text; next_at int;
begin
 if target_player is null or target_player<>auth.uid() then return null;end if;perform public.ensure_daily_state(target_player);base:=public.get_player_game_state_milestone4(target_player);select founder_points into fp from public.player_season_progress where player_id=target_player and season_id='season-0';current_rank:=case when fp>=3000 then 'Guaranteed' when fp>=2000 then 'Priority' when fp>=1200 then 'Whitelist' when fp>=500 then 'Citizen' else 'Settler' end;next_at:=case when fp<500 then 500 when fp<1200 then 1200 when fp<2000 then 2000 when fp<3000 then 3000 else null end;next_rank:=case next_at when 500 then 'Citizen' when 1200 then 'Whitelist' when 2000 then 'Priority' when 3000 then 'Guaranteed' end;
 return base||jsonb_build_object('economyVersion',1,'productionHistory',coalesce((select jsonb_agg(x) from(select jsonb_build_object('id',bp.id,'businessType',pb.business_id,'recipeId',bp.recipe_id,'startedAt',bp.started_at,'readyAt',bp.ready_at,'claimedAt',bp.claimed_at)x from public.business_productions bp join public.player_businesses pb on pb.id=bp.business_id where bp.player_id=target_player order by bp.started_at desc limit 15)s),'[]'::jsonb),'orders',(base->'orders')||jsonb_build_object('active',coalesce((select jsonb_agg(jsonb_build_object('id',d.order_id,'title',n.title,'npc',case d.order_id when 'feed_workers' then 'Chef' when 'workshop_repairs' then 'Foreman' when 'tool_delivery' then 'Merchant' else 'Builder' end,'requirements',case d.order_id when 'repair_old_bridge' then '{"wood":16,"stone":14}'::jsonb when 'feed_workers' then '{"food":12}'::jsonb when 'workshop_repairs' then '{"wood":8,"iron":4}'::jsonb when 'road_reinforcement' then '{"stone":10,"wood":5}'::jsonb else '{"tools":2}'::jsonb end,'rewards',case d.order_id when 'repair_old_bridge' then '{"coins":180,"xp":40}'::jsonb when 'feed_workers' then '{"coins":120,"xp":20}'::jsonb when 'workshop_repairs' then '{"coins":170,"xp":25}'::jsonb when 'road_reinforcement' then '{"coins":150,"xp":22}'::jsonb else '{"coins":260,"xp":35}'::jsonb end,'completed',exists(select 1 from public.player_orders po where po.player_id=target_player and po.order_id=d.order_id and po.order_date=current_date)) order by d.slot) from public.player_daily_orders d join public.npc_orders n on n.id=d.order_id where d.player_id=target_player and d.order_date=current_date),'[]'::jsonb)),'market',(base->'market')||jsonb_build_object('recentTransactions',coalesce((select jsonb_agg(x) from(select jsonb_build_object('id',m.id,'side',m.side,'resource',m.resource,'quantity',m.quantity,'unitPrice',m.unit_price,'gross',m.gross,'fee',m.fee,'net',m.net,'createdAt',m.created_at)x from public.market_transactions m where m.player_id=target_player order by m.created_at desc limit 20)s),'[]'::jsonb)),'season',(base->'season')||jsonb_build_object('rank',current_rank,'nextRank',next_rank,'nextRankAt',next_at,'longestStreak',(select longest_streak from public.player_season_progress where player_id=target_player and season_id='season-0'),'lastActiveQuestDate',(select last_active_quest_date from public.player_season_progress where player_id=target_player and season_id='season-0'),'weeklyCycle',floor((select streak from public.player_season_progress where player_id=target_player and season_id='season-0')/7),'weeklyRewardClaimed',(select weekly_cycle_claimed>=floor(streak/7) from public.player_season_progress where player_id=target_player and season_id='season-0'),'dailyQuests',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'title',q.title,'progress',pq.progress,'target',q.target,'founderPoints',q.founder_points,'completed',pq.progress>=q.target,'claimed',pq.claimed_at is not null) order by q.id) from public.player_quests pq join public.quests q on q.id=pq.quest_id where pq.player_id=target_player and pq.quest_date=current_date),'[]'::jsonb),'achievements',jsonb_build_array(jsonb_build_object('id','first_shift','title','First Shift','founderPoints',20,'eligible',(select jobs_completed>=1 from public.residents where player_id=target_player),'claimed',exists(select 1 from public.achievement_claims where player_id=target_player and achievement_id='first_shift')),jsonb_build_object('id','resource_worker','title','Resource Worker','founderPoints',40,'eligible',(select jobs_completed>=50 from public.residents where player_id=target_player),'claimed',exists(select 1 from public.achievement_claims where player_id=target_player and achievement_id='resource_worker')),jsonb_build_object('id','local_merchant','title','Local Merchant','founderPoints',40,'eligible',(select trades_completed>=20 from public.residents where player_id=target_player),'claimed',exists(select 1 from public.achievement_claims where player_id=target_player and achievement_id='local_merchant')),jsonb_build_object('id','first_builder','title','First Builder','founderPoints',30,'eligible',(select level>=2 from public.properties where player_id=target_player),'claimed',exists(select 1 from public.achievement_claims where player_id=target_player and achievement_id='first_builder')),jsonb_build_object('id','business_owner','title','Business Owner','founderPoints',35,'eligible',exists(select 1 from public.player_businesses where player_id=target_player),'claimed',exists(select 1 from public.achievement_claims where player_id=target_player and achievement_id='business_owner')),jsonb_build_object('id','specialist','title','Specialist','founderPoints',50,'eligible',exists(select 1 from public.player_skills where player_id=target_player and xp>=150),'claimed',exists(select 1 from public.achievement_claims where player_id=target_player and achievement_id='specialist')),jsonb_build_object('id','founding_citizen','title','Founding Citizen','founderPoints',75,'eligible',fp>=1200,'claimed',exists(select 1 from public.achievement_claims where player_id=target_player and achievement_id='founding_citizen'))),'recentFounderPoints',coalesce((select jsonb_agg(x) from(select jsonb_build_object('id',h.id,'amount',h.amount,'reason',h.reason,'createdAt',h.created_at)x from public.founder_point_history h where h.player_id=target_player order by h.created_at desc limit 20)s),'[]'::jsonb)));
end $$;

create or replace function public.grant_founder_points(pid uuid,reward int,reason_name text,ref uuid) returns void language plpgsql security definer set search_path='' as $$
begin update public.player_season_progress set founder_points=founder_points+reward,rank=case when founder_points+reward>=3000 then 'Guaranteed' when founder_points+reward>=2000 then 'Priority' when founder_points+reward>=1200 then 'Whitelist' when founder_points+reward>=500 then 'Citizen' else 'Settler' end where player_id=pid and season_id='season-0';insert into public.founder_point_history(player_id,amount,reason,reference_id)values(pid,reward,reason_name,ref);end $$;
create or replace function public.claim_daily_quest(requested_quest text,request_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare pid uuid:=auth.uid();q public.player_quests%rowtype;reward int;sp public.player_season_progress%rowtype;ref uuid:=gen_random_uuid();result jsonb;
begin if pid is null then raise exception 'Authentication required';end if;perform public.check_rate_limit(pid,'DAILY_QUEST_CLAIM',12,60);perform pg_advisory_xact_lock(hashtextextended(pid::text,51));perform public.ensure_daily_state(pid);select * into q from public.player_quests where player_id=pid and quest_id=requested_quest and quest_date=current_date for update;if q.claimed_at is not null then raise exception 'Quest already claimed';end if;select founder_points into reward from public.quests where id=requested_quest and q.progress>=target;if reward is null then raise exception 'Quest not complete';end if;select * into sp from public.player_season_progress where player_id=pid and season_id='season-0' for update;if sp.fp_day<>current_date then sp.daily_fp_earned:=0;end if;if sp.daily_fp_earned+reward>45 then raise exception 'Daily Founder Point cap exceeded';end if;update public.player_quests set claimed_at=now() where player_id=pid and quest_id=requested_quest and quest_date=current_date;update public.player_season_progress set daily_fp_earned=case when fp_day=current_date then daily_fp_earned+reward else reward end,fp_day=current_date,streak=case when last_active_quest_date=current_date then streak when last_active_quest_date=current_date-1 then streak+1 else 1 end,longest_streak=greatest(longest_streak,case when last_active_quest_date=current_date then streak when last_active_quest_date=current_date-1 then streak+1 else 1 end),last_active_quest_date=current_date where player_id=pid and season_id='season-0';perform public.grant_founder_points(pid,reward,'DAILY_QUEST',ref);insert into public.action_telemetry(player_id,event_type)values(pid,'DAILY_QUEST_CLAIM');result:=jsonb_build_object('state',public.get_player_game_state(pid),'message','Daily quest claimed');return result;end $$;
create or replace function public.claim_weekly_streak(request_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare pid uuid:=auth.uid();sp public.player_season_progress%rowtype;cycle int;ref uuid:=gen_random_uuid();begin if pid is null then raise exception 'Authentication required';end if;perform pg_advisory_xact_lock(hashtextextended(pid::text,52));select * into sp from public.player_season_progress where player_id=pid and season_id='season-0' for update;cycle:=floor(sp.streak/7);if cycle<1 or sp.weekly_cycle_claimed>=cycle then raise exception 'Weekly reward unavailable';end if;update public.player_season_progress set weekly_cycle_claimed=cycle,founder_seals=founder_seals+1 where player_id=pid and season_id='season-0';perform public.grant_founder_points(pid,25,'WEEKLY_STREAK',ref);return jsonb_build_object('state',public.get_player_game_state(pid),'message','Weekly streak claimed');end $$;
create or replace function public.claim_achievement(requested_achievement text,request_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare pid uuid:=auth.uid();eligible boolean:=false;reward int;ref uuid:=gen_random_uuid();begin if pid is null then raise exception 'Authentication required';end if;perform pg_advisory_xact_lock(hashtextextended(pid::text,53));if exists(select 1 from public.achievement_claims where player_id=pid and achievement_id=requested_achievement) then raise exception 'Achievement already claimed';end if;case requested_achievement when 'first_shift' then select jobs_completed>=1,20 into eligible,reward from public.residents where player_id=pid;when 'resource_worker' then select jobs_completed>=50,40 into eligible,reward from public.residents where player_id=pid;when 'local_merchant' then select trades_completed>=20,40 into eligible,reward from public.residents where player_id=pid;when 'first_builder' then select level>=2,30 into eligible,reward from public.properties where player_id=pid;when 'business_owner' then select exists(select 1 from public.player_businesses where player_id=pid),35 into eligible,reward;when 'specialist' then select exists(select 1 from public.player_skills where player_id=pid and xp>=150),50 into eligible,reward;when 'founding_citizen' then select founder_points>=1200,75 into eligible,reward from public.player_season_progress where player_id=pid and season_id='season-0';else raise exception 'Unknown achievement';end case;if not eligible then raise exception 'Achievement not unlocked';end if;insert into public.achievement_claims values(pid,requested_achievement,now(),ref);perform public.grant_founder_points(pid,reward,'ACHIEVEMENT',ref);insert into public.action_telemetry(player_id,event_type,metadata)values(pid,'ACHIEVEMENT_CLAIM',jsonb_build_object('achievement',requested_achievement));return jsonb_build_object('state',public.get_player_game_state(pid),'message','Achievement claimed');end $$;

create or replace view public.daily_economy_metrics with(security_invoker=true) as select created_at::date metric_date,sum(case when resource='coins' and amount>0 then amount else 0 end) coins_created,sum(case when resource='coins' and amount<0 then -amount else 0 end) coins_destroyed,sum(case when transaction_type='MARKET_FEE' then -amount else 0 end) marketplace_fees,sum(case when transaction_type='PROPERTY_UPGRADE_COIN_COST' then -amount else 0 end) property_spending,sum(case when transaction_type='CRAFT_COIN_COST' then -amount else 0 end) crafting_spending,sum(case when transaction_type='NPC_ORDER_REWARD' and resource='coins' then amount else 0 end) npc_rewards,sum(case when transaction_type='JOB_REWARD' and resource='coins' then amount else 0 end) job_rewards,sum(case when transaction_type='BUSINESS_NET_REVENUE' then amount else 0 end) business_revenue from public.economy_transactions group by created_at::date;
create or replace function public.get_admin_economy_dashboard() returns jsonb language plpgsql security definer set search_path='' as $$declare pid uuid:=auth.uid();begin if not exists(select 1 from public.profiles where id=pid and app_role='admin')then raise exception 'ADMIN_REQUIRED';end if;return jsonb_build_object('economyVersion',1,'today',(select to_jsonb(m) from public.daily_economy_metrics m where metric_date=current_date),'marketplace',(select jsonb_build_object('buyVolume',coalesce(sum(quantity)filter(where side='buy'),0),'sellVolume',coalesce(sum(quantity)filter(where side='sell'),0),'fees',coalesce(sum(fee),0))from public.market_transactions where created_at::date=current_date),'businessTaxes',(select coins_removed from public.business_tax_totals where id),'averageStorageUsage',(select avg(public.effective_storage_used(player_id)::numeric/nullif(storage_capacity,0)) from public.properties),'propertyDistribution',(select jsonb_object_agg(level,count)from(select level,count(*)count from public.properties group by level)s),'businessDistribution',(select jsonb_object_agg(business_id,count)from(select business_id,count(*)count from public.player_businesses group by business_id)s),'dailyActivePlayers',(select count(distinct player_id)from public.action_telemetry where occurred_at::date=current_date),'abuseSignals',(select count(*)from public.abuse_signals where reviewed_at is null));end $$;
revoke execute on function public.ensure_daily_state(uuid),public.check_rate_limit(uuid,text,int,int),public.grant_founder_points(uuid,int,text,uuid),public.claim_daily_quest(text,uuid),public.claim_weekly_streak(uuid),public.claim_achievement(text,uuid),public.get_admin_economy_dashboard() from public,anon;
grant execute on function public.claim_daily_quest(text,uuid),public.claim_weekly_streak(uuid),public.claim_achievement(text,uuid),public.get_admin_economy_dashboard() to authenticated;

create or replace function public.complete_npc_order(requested_order text,request_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare pid uuid:=auth.uid();req1 text;amt1 int;req2 text;amt2 int;reward_coins int;reward_xp int;before1 int;before2 int;coins_before bigint;xp_before int;ref uuid:=gen_random_uuid();result jsonb;
begin if pid is null then raise exception 'Authentication required';end if;perform public.check_rate_limit(pid,'NPC_ORDER',8,60);perform pg_advisory_xact_lock(hashtextextended(pid::text,54));perform public.ensure_daily_state(pid);if not exists(select 1 from public.player_daily_orders where player_id=pid and order_date=current_date and order_id=requested_order)then raise exception 'Order is not active today';end if;if exists(select 1 from public.player_orders where player_id=pid and order_id=requested_order and order_date=current_date)then raise exception 'Order already completed';end if;case requested_order when 'repair_old_bridge' then req1:='wood';amt1:=16;req2:='stone';amt2:=14;reward_coins:=180;reward_xp:=40;when 'feed_workers' then req1:='food';amt1:=12;reward_coins:=120;reward_xp:=20;when 'workshop_repairs' then req1:='wood';amt1:=8;req2:='iron';amt2:=4;reward_coins:=170;reward_xp:=25;when 'road_reinforcement' then req1:='stone';amt1:=10;req2:='wood';amt2:=5;reward_coins:=150;reward_xp:=22;when 'tool_delivery' then req1:='tools';amt1:=2;reward_coins:=260;reward_xp:=35;else raise exception 'Unsupported order';end case;select amount into before1 from public.player_resources where player_id=pid and resource=req1 for update;if before1<amt1 then raise exception 'Not enough %',req1;end if;if req2 is not null then select amount into before2 from public.player_resources where player_id=pid and resource=req2 for update;if before2<amt2 then raise exception 'Not enough %',req2;end if;end if;select coins into coins_before from public.player_economy where player_id=pid for update;select xp into xp_before from public.residents where player_id=pid for update;update public.player_resources set amount=amount-amt1 where player_id=pid and resource=req1;if req2 is not null then update public.player_resources set amount=amount-amt2 where player_id=pid and resource=req2;end if;update public.player_economy set coins=coins+reward_coins where player_id=pid;update public.residents set xp=xp+reward_xp,level=1+((xp+reward_xp)/100),orders_completed=orders_completed+1 where player_id=pid;insert into public.player_orders(player_id,order_id,completed_at,reference_id,order_date)values(pid,requested_order,now(),ref,current_date);insert into public.player_quests(player_id,quest_id,progress,quest_date)values(pid,'daily-order-1',1,current_date)on conflict(player_id,quest_id,quest_date)do update set progress=least(1,public.player_quests.progress+1);insert into public.economy_transactions(player_id,transaction_type,resource,amount,balance_before,balance_after,reference_id)values(pid,'NPC_ORDER_RESOURCE_COST',req1::public.resource_kind,-amt1,before1,before1-amt1,ref),(pid,'NPC_ORDER_REWARD','coins',reward_coins,coins_before,coins_before+reward_coins,ref),(pid,'NPC_ORDER_REWARD','xp',reward_xp,xp_before,xp_before+reward_xp,ref);if req2 is not null then insert into public.economy_transactions(player_id,transaction_type,resource,amount,balance_before,balance_after,reference_id)values(pid,'NPC_ORDER_RESOURCE_COST',req2::public.resource_kind,-amt2,before2,before2-amt2,ref);end if;insert into public.action_telemetry(player_id,event_type,metadata)values(pid,'NPC_ORDER_COMPLETED',jsonb_build_object('order',requested_order));result:=jsonb_build_object('state',public.get_player_game_state(pid),'message','Order delivered');return result;end $$;
